-- Substitute the payload token with JSON from prepare-futbalnet-clubs.py.
-- Reject a payload containing the delimiter before substitution.
with imported as (select * from jsonb_to_recordset($clubs_import$__PAYLOAD__$clubs_import$::jsonb) as x(id text,name text,short_name text,city text,logo_placeholder text,logo_url text,source_id text,source_url text,status text)), applied as (insert into public.clubs(id,name,short_name,sport,country,city,logo_placeholder,logo_url,source,source_id,source_url,status) select id,name,short_name,'football','Slovensko',city,logo_placeholder,logo_url,'sportnet_futbalnet',source_id,source_url,status from imported on conflict(id) do update set source=excluded.source,source_id=excluded.source_id,source_url=excluded.source_url,logo_url=coalesce(public.clubs.logo_url,excluded.logo_url),updated_at=now() where public.clubs.source<>'sportnet_futbalnet' or public.clubs.source_id=excluded.source_id returning id) select count(*) as imported from applied;
